  SkySceneKit.say({english="............ Came to save the world of Pokémon? I did...?", french="... ... ... ... Sauver le monde Pokémon? Ah bon?", german="............ Ich soll die Welt der Pokémon retten? ICH...?", italian="... Salvare il mondo dei Pokémon? Questo è...?", spanish="¿Qué...? ¿Salvar el mundo de los Pokémon? ¿Por eso estoy aquí?"})
  SkySceneKit.say({english="............ Came to save the world of Pokémon? I did...?", french="... ... ... ... Sauver le monde Pokémon? Ah bon?", german="............ Ich soll die Welt der Pokémon retten? ICH...?", italian="... Salvare il mondo dei Pokémon? Questo è...?", spanish="¿Cómo...? ¿Salvar el mundo de los Pokémon? ¿Para eso he venido aquí?"})
  SkySceneKit.say({english="Yes. We learned that this world faced extinction.", french="Oui. Nous avons appris que ce monde allait disparaître.", german="Ja. Wir hatten erkannt, dass diese Welt auf der Schwelle zur Vernichtung stand.", italian="Sì. Una minaccia incombeva su questo mondo, che era destinato a scomparire.", spanish="Sí. Nos enteramos de que el mundo iba a ser destruido."})
