  SkySceneKit.say({english="I'm not anything special like that?!", french="Je n'ai vraiment rien de spécial!", german="An mir ist nichts Besonderes!!!", italian="Non vorrai dire che sono un tipo così speciale?", spanish="¡No puedo ayudaros! ¡No soy especial!"})
  SkySceneKit.say({english="Wa... Wait a second! Hero? Me? That's too much!", french="Mais... attends une seconde! Une héroïne? Moi? C'est trop fort!", german="Augen- Augenblick mal! Ich? Ein Held? So ein Unsinn!", italian="Ma... aspetta un attimo! Io? Sono io quell'essere umano eroico?", spanish="¡¿Qué...?! ¡Un momento! ¿Yo? ¡Yo no puedo!"})
  SkySceneKit.say({english="I'm not anything special like that?!", french="Je n'ai vraiment rien de spécial!", german="An mir ist nichts Besonderes!!!", italian="Non vorrai dire che sono un tipo così speciale?", spanish="¡No puedo ayudaros! ¡No soy nada del otro mundo!"})
  SkySceneKit.say({english="Yes. That is also what you said the first time we met.", french="Mais si. C'est aussi ce que tu as dit lors de notre première rencontre.", german="Ja. Das hast du bei unserer ersten Begegnung auch gesagt.", italian="Certo. Al nostro primo incontro hai detto più o meno la stessa cosa.", spanish="Sí. Eso dijiste la primera vez que nos encontramos."})
  SkySceneKit.say({english="You said you were not strong.", french="Tu as dit que tu manquais de force.", german="Du sagtest, du seist nicht stark.", italian="Hai detto di non essere forte.", spanish="Dijiste que te faltaba la fuerza necesaria..."})
  SkySceneKit.say({english="But what we sought was not power merely for display...", french="Mais nous ne cherchions pas de la force brute...", german="Doch wir suchten nicht bloße Stärke oder Macht...", italian="Ma noi non cercavamo qualcuno che ostentasse la propria forza...", spanish="Pero la fuerza que nosotros buscábamos no es la de los músculos..."})
  SkySceneKit.say({english="We sought true courage.", french="Nous cherchions le vrai courage.", german="Wir suchten wahren Mut.", italian="Noi cercavamo il vero coraggio.", spanish="Buscábamos valor, fuerza interior."})
  SkySceneKit.say({english="True courage...? That... I'm even less confident about that.", french="Le vrai courage? Je... je suis sceptique.", german="Wahren Mut...? Mut... Den habe ich noch viel weniger!", italian="Il vero coraggio? Non... credo proprio che tu stia parlando di me.", spanish="¿Valor...? De eso aún creo que tengo menos."})
  SkySceneKit.say({english="True courage...? That... I'm even less confident about that.", french="Le vrai courage? Je... je suis sceptique.", german="Wahren Mut...? Mut... Den habe ich noch viel weniger!", italian="Il vero coraggio? Non... credo proprio che tu stia parlando di me.", spanish="¿Valor...? De eso aún creo que tengo menos."})
  SkySceneKit.say({english="That, too, is what you said when we met.", french="C'est aussi ce que tu as dit la première fois.", german="Auch das hast du damals gesagt.", italian="Al nostro primo incontro hai detto anche questo.", spanish="Eso también lo dijiste cuando nos conocimos."})
