  SkySceneKit.say({english="To see if you were worthy to be our hero or not...", french="Pour savoir si tu avais assez de courage...", german="Um festzustellen, ob du es wert seist, unser Held zu werden...", italian="Per vedere se fossi veramente audace come pensavamo...", spanish="Para saber si eras quien buscábamos..."})
  SkySceneKit.say({english="You asked that we put you to the test.", french="... tu as demandé à passer une épreuve.", german="Batest du uns, dich auf die Probe zu stellen.", italian="... Ci hai chiesto di metterti alla prova.", spanish="pediste que te pusiésemos a prueba."})
  SkySceneKit.say({english="And only if you were found to be truly worthy...", french="Et ce n'est que lorsque nous serions sûrs que tu le méritais...", german="Und nur, wenn du dich als würdig erweisen würdest...", italian="Solo se avessi dimostrato di essere meritevole...", spanish="Solo cuando no hubiera duda de que eras quien buscábamos..."})
  SkySceneKit.say({english="Then you were to be told the truth.", french="... que nous pourrions te dire la vérité.", german="Sollten wir dir die volle Wahrheit sagen.", italian="... Ti avremmo detto la verità.", spanish="te contaríamos la verdad."})
  SkySceneKit.say({english="To fulfill your role clear of heart and mind, you then chose to erase your memory as a human...", french="Pour jouer cette fonction l'esprit et le cur libre, tu as demandé qu'on efface tes souvenirs d'humain...", german="Um deine Rolle mit reinem Geist und Herzen zu erfüllen, wolltest du alle menschlichen Erinnerungen vergessen...", italian="Per portare a termine il tuo compito con animo sereno, hai voluto can- cellare i ricordi della tua vita da umano.", spanish="Para poder afrontar tu misión, pediste que borrásemos tus recuerdos de cuando eras un ser humano..."})
  SkySceneKit.say({english="And became a Pokémon of your own will to fight alongside your friends.", french="Et tu as choisi librement de devenir un Pokémon pour lutter aux côtés de tes amis.", german="Und so wurdest du freiwillig ein Pokémon, um gemeinsam mit deinen Freunden zu kämpfen.", italian="E così hai preso le sembianze di un Pokémon per lottare insieme ai tuoi amici.", spanish="y así poder sentirte un auténtico Pokémon con el deseo de luchar al lado de los tuyos."})
  SkySceneKit.say({english="That is how you came to be in this world.", french="C'est pour cette raison que tu es dans ce monde.", german="So kam es, dass du in dieser Welt gelandet bist.", italian="Ecco come hai fatto la tua comparsa in questo mondo.", spanish="Así es como acabaste en este mundo."})
  SkySceneKit.say({english="I... I did that?", french="Je... j'ai fait ça?", german="Ich... Ich habe das freiwillig getan?", italian="Io... ho fatto veramente tutto ciò?", spanish="Yo... ¿Yo hice todo eso?"})
  SkySceneKit.say({english="I... I did that?", french="Je... j'ai fait ça?", german="Ich... Ich habe das freiwillig getan?", italian="Io... ho fatto veramente tutto ciò?", spanish="Yo... ¿He hecho yo todo eso?"})
